1	<!doctype html>
2	<html lang="zh-CN">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width,initial-scale=1">
6	<title>发货哨兵 · FulfillSentinel</title>
7	<style>
8	  :root{
9	    --bg:#EBEEF2; --panel:#FBFCFD; --panel-2:#F0F3F6; --panel-3:#E9EDF1;
10	    --ink:#131A22; --ink-2:#4A5563; --ink-3:#8A94A2;
11	    --line:#D6DDE5; --line-2:#E6EBF0;
12	    --accent:#1B7FC4; --accent-2:#1C9BB8;
13	    --crit:#D03B3B; --crit-bg:rgba(208,59,59,.11); --crit-line:rgba(208,59,59,.42);
14	    --warn:#B5770E; --warn-bg:rgba(200,130,20,.14); --warn-line:rgba(200,130,20,.42);
15	    --good:#0C8A3C; --good-bg:rgba(12,138,60,.12); --good-line:rgba(12,138,60,.4);
16	    --info:#5B5AA6; --info-bg:rgba(91,90,166,.12);
17	    /* 平台分类色（dataviz 校验过的前 4 槽：blue/aqua/yellow/green，固定顺序） */
18	    --p-amazon:#2a78d6; --p-tiktok:#1baf7a; --p-temu:#eda100; --p-shein:#008300; --p-other:#8A94A2;
19	    --shadow:0 1px 2px rgba(19,26,34,.05),0 6px 20px rgba(19,26,34,.07);
20	    --font-sans:"Microsoft YaHei","PingFang SC","Hiragino Sans GB","Noto Sans CJK SC",-apple-system,"Segoe UI",Roboto,sans-serif;
21	    --font-mono:"Cascadia Code","JetBrains Mono","SF Mono","Consolas",ui-monospace,Menlo,monospace;
22	  }
23	  @media (prefers-color-scheme:dark){
24	    :root{
25	      --bg:#0C1117; --panel:#141A22; --panel-2:#1A212B; --panel-3:#212a35;
26	      --ink:#E9EEF3; --ink-2:#99A5B3; --ink-3:#5E6A78;
27	      --line:#242D38; --line-2:#1D2530;
28	      --accent:#3AA4E6; --accent-2:#3FC0D4;
29	      --crit:#EF565C; --crit-bg:rgba(239,86,92,.15); --crit-line:rgba(239,86,92,.5);
30	      --warn:#E0A63B; --warn-bg:rgba(224,166,59,.15); --warn-line:rgba(224,166,59,.45);
31	      --good:#41BF89; --good-bg:rgba(65,191,137,.14); --good-line:rgba(65,191,137,.45);
32	      --info:#9085e9; --info-bg:rgba(144,133,233,.16);
33	      --p-amazon:#3987e5; --p-tiktok:#199e70; --p-temu:#c98500; --p-shein:#33a033; --p-other:#5E6A78;
34	      --shadow:0 1px 2px rgba(0,0,0,.3),0 8px 24px rgba(0,0,0,.36);
35	    }
36	  }
37	  :root[data-theme="light"]{--bg:#EBEEF2;--panel:#FBFCFD;--panel-2:#F0F3F6;--panel-3:#E9EDF1;--ink:#131A22;--ink-2:#4A5563;--ink-3:#8A94A2;--line:#D6DDE5;--line-2:#E6EBF0;--accent:#1B7FC4;--accent-2:#1C9BB8;--crit:#D03B3B;--crit-bg:rgba(208,59,59,.11);--crit-line:rgba(208,59,59,.42);--warn:#B5770E;--warn-bg:rgba(200,130,20,.14);--warn-line:rgba(200,130,20,.42);--good:#0C8A3C;--good-bg:rgba(12,138,60,.12);--good-line:rgba(12,138,60,.4);--info:#5B5AA6;--info-bg:rgba(91,90,166,.12);--p-amazon:#2a78d6;--p-tiktok:#1baf7a;--p-temu:#eda100;--p-shein:#008300;--p-other:#8A94A2;--shadow:0 1px 2px rgba(19,26,34,.05),0 6px 20px rgba(19,26,34,.07);}
38	  :root[data-theme="dark"]{--bg:#0C1117;--panel:#141A22;--panel-2:#1A212B;--panel-3:#212a35;--ink:#E9EEF3;--ink-2:#99A5B3;--ink-3:#5E6A78;--line:#242D38;--line-2:#1D2530;--accent:#3AA4E6;--accent-2:#3FC0D4;--crit:#EF565C;--crit-bg:rgba(239,86,92,.15);--crit-line:rgba(239,86,92,.5);--warn:#E0A63B;--warn-bg:rgba(224,166,59,.15);--warn-line:rgba(224,166,59,.45);--good:#41BF89;--good-bg:rgba(65,191,137,.14);--good-line:rgba(65,191,137,.45);--info:#9085e9;--info-bg:rgba(144,133,233,.16);--p-amazon:#3987e5;--p-tiktok:#199e70;--p-temu:#c98500;--p-shein:#33a033;--p-other:#5E6A78;--shadow:0 1px 2px rgba(0,0,0,.3),0 8px 24px rgba(0,0,0,.36);}
39	
40	  *{box-sizing:border-box;}
41	  html,body{margin:0;}
42	  body{background:var(--bg);color:var(--ink);font-family:var(--font-sans);font-size:14px;line-height:1.5;-webkit-font-smoothing:antialiased;}
43	  .mono{font-family:var(--font-mono);font-variant-numeric:tabular-nums;}
44	  .app{max-width:1320px;margin:0 auto;padding:clamp(12px,2vw,22px);display:flex;flex-direction:column;gap:14px;}
45	  :focus-visible{outline:2px solid var(--accent);outline-offset:2px;border-radius:4px;}
46	  button{font-family:inherit;cursor:pointer;color:inherit;}
47	  .panel{background:var(--panel);border:1px solid var(--line);border-radius:14px;box-shadow:var(--shadow);}
48	
49	  /* topbar */
50	  .top{display:flex;align-items:center;gap:12px 18px;flex-wrap:wrap;padding:13px 18px;}
51	  .brand{display:flex;align-items:center;gap:11px;}
52	  .logo{width:40px;height:40px;border-radius:11px;background:linear-gradient(135deg,var(--accent),var(--accent-2));display:grid;place-items:center;color:#fff;font-size:20px;position:relative;overflow:hidden;flex-shrink:0;}
53	  .logo::after{content:"";position:absolute;inset:0;background:conic-gradient(from 0deg,transparent 0deg,rgba(255,255,255,.4) 42deg,transparent 84deg);animation:sweep 3.6s linear infinite;}
54	  @keyframes sweep{to{transform:rotate(360deg);}}
55	  .bt{font-weight:800;font-size:1.14rem;letter-spacing:-.01em;}
56	  .bs{font-family:var(--font-mono);font-size:.6rem;letter-spacing:.16em;text-transform:uppercase;color:var(--ink-3);}
57	  .badges{display:flex;gap:7px;flex-wrap:wrap;}
58	  .badge{font-family:var(--font-mono);font-size:.6rem;letter-spacing:.1em;color:var(--good);border:1px solid var(--good-line);background:var(--good-bg);border-radius:6px;padding:3px 8px;font-weight:700;text-transform:uppercase;}
59	  .sources{display:flex;gap:8px;flex-wrap:wrap;margin-left:auto;}
60	  .src{display:flex;align-items:center;gap:7px;background:var(--panel-2);border:1px solid var(--line-2);border-radius:9px;padding:6px 11px;font-size:.78rem;}
61	  .src .dot{width:8px;height:8px;border-radius:50%;background:var(--good);box-shadow:0 0 0 3px var(--good-bg);}
62	  .src b{font-weight:700;}
63	  .src .c{font-family:var(--font-mono);color:var(--ink-3);font-size:.7rem;}
64	  .ttoggle{background:var(--panel-2);border:1px solid var(--line-2);border-radius:9px;padding:7px 10px;font-size:.9rem;}
65	
66	  /* AI summary */
67	  .ai{display:flex;gap:13px;align-items:flex-start;padding:14px 18px;background:linear-gradient(100deg,var(--crit-bg),transparent 62%);border-left:3px solid var(--crit);}
68	  .ai.ok{background:linear-gradient(100deg,var(--good-bg),transparent 62%);border-left-color:var(--good);}
69	  .ai .ic{font-size:18px;flex-shrink:0;margin-top:1px;}
70	  .ai .txt{font-size:.93rem;color:var(--ink);line-height:1.62;}
71	  .ai .txt b{color:var(--crit);font-weight:800;}
72	  .ai .txt .g{color:var(--warn);font-weight:700;}
73	  .ai .txt .ok{color:var(--good);font-weight:700;}
74	
75	  /* KPI */
76	  .kpis{display:grid;grid-template-columns:repeat(6,1fr);gap:11px;}
77	  .kpi{padding:13px 15px;display:flex;flex-direction:column;gap:3px;position:relative;overflow:hidden;}
78	  .kpi .k-l{font-size:.72rem;color:var(--ink-3);font-weight:600;letter-spacing:.02em;}
79	  .kpi .k-v{font-size:1.85rem;font-weight:800;letter-spacing:-.02em;line-height:1.05;}
80	  .kpi .k-s{font-size:.7rem;color:var(--ink-3);}
81	  .kpi.crit .k-v{color:var(--crit);} .kpi.warn .k-v{color:var(--warn);} .kpi.good .k-v{color:var(--good);}
82	  .kpi .spark{position:absolute;right:10px;top:11px;font-size:1rem;opacity:.5;}
83	
84	  .grid{display:grid;grid-template-columns:340px 1fr;gap:14px;align-items:start;}
85	  @media(max-width:980px){.grid{grid-template-columns:1fr;}.kpis{grid-template-columns:repeat(3,1fr);}}
86	  @media(max-width:560px){.kpis{grid-template-columns:repeat(2,1fr);}}
87	
88	  .card{padding:14px 16px;}
89	  .card h3{margin:0 0 11px;font-size:.82rem;font-weight:800;letter-spacing:.02em;display:flex;align-items:center;gap:8px;}
90	  .card h3 .n{margin-left:auto;font-family:var(--font-mono);font-size:.72rem;color:var(--ink-3);font-weight:600;}
91	
92	  /* anomaly triage */
93	  .anom{display:flex;flex-direction:column;gap:7px;}
94	  .arow{display:flex;align-items:center;gap:10px;padding:9px 11px;border-radius:10px;border:1px solid var(--line-2);background:var(--panel-2);cursor:pointer;transition:.12s;}
95	  .arow:hover{border-color:var(--accent);transform:translateX(2px);}
96	  .arow.active{border-color:var(--accent);box-shadow:0 0 0 2px var(--accent-2) inset;}
97	  .arow .ai-ic{font-size:15px;width:18px;text-align:center;}
98	  .arow .a-name{font-weight:700;font-size:.86rem;}
99	  .arow .a-desc{font-size:.7rem;color:var(--ink-3);margin-top:1px;}
100	  .arow .a-cnt{margin-left:auto;font-family:var(--font-mono);font-weight:800;font-size:1.05rem;min-width:28px;text-align:right;}
101	  .arow.crit{background:var(--crit-bg);border-color:var(--crit-line);} .arow.crit .a-cnt{color:var(--crit);}
102	  .arow.warn .a-cnt{color:var(--warn);}
103	  .arow.info .a-cnt{color:var(--info);}
104	  .arow.zero{opacity:.5;} .arow.zero .a-cnt{color:var(--ink-3);}
105	
106	  /* mini distributions */
107	  .distrow{display:flex;align-items:center;gap:9px;margin-bottom:7px;}
108	  .distrow .lb{width:78px;font-size:.76rem;color:var(--ink-2);flex-shrink:0;}
109	  .distrow .track{flex:1;height:16px;background:var(--panel-3);border-radius:5px;overflow:hidden;position:relative;}
110	  .distrow .fill{height:100%;border-radius:5px;}
111	  .distrow .vv{font-family:var(--font-mono);font-size:.74rem;color:var(--ink-2);width:66px;text-align:right;flex-shrink:0;}
112	
113	  .sla{display:flex;gap:14px;align-items:center;flex-wrap:wrap;}
114	  .sla .hero{font-size:2.6rem;font-weight:800;color:var(--good);letter-spacing:-.03em;line-height:1;}
115	  .sla .sub{font-size:.76rem;color:var(--ink-3);margin-top:2px;}
116	  .sla .pill{font-family:var(--font-mono);font-size:.74rem;background:var(--panel-2);border:1px solid var(--line-2);border-radius:7px;padding:4px 9px;}
117	
118	  /* toolbar */
119	  .toolbar{display:flex;gap:9px;align-items:center;flex-wrap:wrap;margin-bottom:11px;}
120	  .search{flex:1;min-width:180px;display:flex;align-items:center;gap:8px;background:var(--panel-2);border:1px solid var(--line-2);border-radius:9px;padding:8px 12px;}
121	  .search input{border:0;background:transparent;outline:0;color:var(--ink);font-family:inherit;font-size:.86rem;width:100%;}
122	  .chips{display:flex;gap:6px;flex-wrap:wrap;}
123	  .chip{font-size:.76rem;border:1px solid var(--line-2);background:var(--panel-2);border-radius:20px;padding:5px 12px;color:var(--ink-2);}
124	  .chip.on{background:var(--accent);border-color:var(--accent);color:#fff;font-weight:700;}
125	  .chip .pf{display:inline-flex;align-items:center;gap:6px;}
126	  .btn{border:1px solid var(--line);background:var(--panel-2);border-radius:9px;padding:8px 13px;font-size:.82rem;font-weight:700;display:inline-flex;align-items:center;gap:7px;}
127	  .btn.primary{background:linear-gradient(135deg,var(--accent),var(--accent-2));border-color:transparent;color:#fff;}
128	
129	  /* table */
130	  .twrap{overflow:auto;max-height:min(74vh,720px);border-radius:10px;border:1px solid var(--line-2);}
131	  table{border-collapse:collapse;width:100%;font-size:.8rem;min-width:920px;}
132	  thead th{position:sticky;top:0;background:var(--panel-3);text-align:left;padding:9px 11px;font-size:.72rem;color:var(--ink-2);font-weight:700;white-space:nowrap;cursor:pointer;user-select:none;border-bottom:1px solid var(--line);}
133	  thead th:hover{color:var(--accent);}
134	  tbody td{padding:9px 11px;border-bottom:1px solid var(--line-2);white-space:nowrap;vertical-align:middle;}
135	  tbody tr:hover{background:var(--panel-2);}
136	  tbody tr.sev-crit{box-shadow:inset 3px 0 0 var(--crit);}
137	  tbody tr.sev-warn{box-shadow:inset 3px 0 0 var(--warn);}
138	  tbody tr.sev-info{box-shadow:inset 3px 0 0 var(--info);}
139	  .pf{display:inline-flex;align-items:center;gap:6px;font-weight:600;}
140	  .pf .pdot{width:8px;height:8px;border-radius:2px;flex-shrink:0;}
141	  .st{font-size:.7rem;padding:2px 8px;border-radius:6px;font-weight:700;border:1px solid transparent;}
142	  .st.pending{color:var(--warn);background:var(--warn-bg);border-color:var(--warn-line);}
143	  .st.shipped{color:var(--good);background:var(--good-bg);border-color:var(--good-line);}
144	  .st.void{color:var(--ink-3);background:var(--panel-3);}
145	  .cd{display:flex;align-items:center;gap:7px;min-width:128px;}
146	  .cd .ct{width:60px;height:7px;border-radius:4px;background:var(--panel-3);overflow:hidden;flex-shrink:0;}
147	  .cd .cf{height:100%;border-radius:4px;}
148	  .cd .cl{font-family:var(--font-mono);font-size:.72rem;}
149	  .tags{display:flex;gap:4px;flex-wrap:wrap;}
150	  .tg{font-size:.64rem;padding:2px 6px;border-radius:5px;font-weight:700;white-space:nowrap;}
151	  .tg.crit{color:var(--crit);background:var(--crit-bg);} .tg.warn{color:var(--warn);background:var(--warn-bg);} .tg.info{color:var(--info);background:var(--info-bg);}
152	  .empty{padding:26px;text-align:center;color:var(--ink-3);}
153	  .stock0{color:var(--crit);font-weight:800;}
154	  .foot{display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap;font-size:.72rem;color:var(--ink-3);padding:4px 6px 12px;}
155	  .foot code{font-family:var(--font-mono);background:var(--panel-2);padding:1px 5px;border-radius:4px;}
156	  @media (prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important;}}
157	</style>
158	</head>
159	<body>
160	<div class="app" id="app">
161	  <div class="top panel">
162	    <div class="brand">
163	      <div class="logo">🛰️</div>
164	      <div>
165	        <div class="bt">发货哨兵 <span style="color:var(--ink-3);font-weight:600;font-size:.8rem;">FulfillSentinel</span></div>
166	        <div class="bs">Cross-platform Fulfillment Watchtower</div>
167	      </div>
168	    </div>
169	    <div class="badges">
170	      <span class="badge">只读 READ-ONLY</span>
171	      <span class="badge">PII 已脱敏</span>
172	      <span class="badge">离线可用 OFFLINE</span>
173	    </div>
174	    <div class="sources" id="sources"></div>
175	    <button class="ttoggle" id="ttoggle" title="切换主题">🌓</button>
176	  </div>
177	
178	  <div class="ai panel" id="ai"></div>
179	
180	  <div class="kpis" id="kpis"></div>
181	
182	  <div class="grid">
183	    <div style="display:flex;flex-direction:column;gap:14px;">
184	      <div class="card panel">
185	        <h3>⚠️ 履约异常预警 <span class="n" id="anomTotal"></span></h3>
186	        <div class="anom" id="anom"></div>
187	      </div>
188	      <div class="card panel">
189	        <h3>🛒 跨系统库存联动 <span class="n" id="invN"></span></h3>
190	        <div id="inv"></div>
191	      </div>
192	      <div class="card panel">
193	        <h3>📦 平台分布 <span class="n" id="platN"></span></h3>
194	        <div id="platDist"></div>
195	      </div>
196	      <div class="card panel">
197	        <h3>⏱️ 发货时效（已发订单）</h3>
198	        <div class="sla" id="sla"></div>
199	      </div>
200	    </div>
201	
202	    <div class="card panel">
203	      <h3>🗂️ 统一订单看板 <span class="n" id="rowN"></span></h3>
204	      <div class="toolbar">
205	        <div class="search">🔎 <input id="q" placeholder="搜索 包裹号 / 平台单号 / SKU / 店铺 …（试试：待发、Temu、断货、卡仓）"></div>
206	        <div class="chips" id="stateChips"></div>
207	        <button class="btn primary" id="exportBtn">⬇ 导出催发清单</button>
208	      </div>
209	      <div class="chips" id="platChips" style="margin-bottom:11px;"></div>
210	      <div class="twrap">
211	        <table id="tbl">
212	          <thead><tr id="thead"></tr></thead>
213	          <tbody id="tbody"></tbody>
214	        </table>
215	      </div>
216	      <div class="foot">
217	        <span id="footInfo"></span>
218	        <span>点左侧异常/平台标签联动筛选 · 表头可排序</span>
219	      </div>
220	    </div>
221	  </div>
222	
223	  <div class="foot" style="justify-content:center;">
224	    数据源 <code id="srcName"></code> · 快照 <code id="snapTime"></code> · 只读聚合，买家 PII 已在解析层剔除，全程无写操作
225	  </div>
226	</div>
227	
228	<script src="data.js"></script>
229	<script>
230	(function(){
231	  const D = window.SENTINEL_DATA;
232	  const app=document.getElementById('app');
233	  if(!D){ app.innerHTML='<div class="empty panel" style="padding:40px">未找到数据。请先运行 <code>python backend/pack.py</code> 生成 data.js。</div>'; return; }
234	
235	  const $=(s)=>document.querySelector(s);
236	  const platColor=(p)=>({'Amazon':'var(--p-amazon)','TikTok':'var(--p-tiktok)','Temu半托管':'var(--p-temu)','SHEIN':'var(--p-shein)'}[p]||'var(--p-other)');
237	  const esc=(s)=>String(s==null?'':s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
238	  const O = D.orders, k=D.kpis, ls=D.lead_stats, ac=D.anomaly_counts;
239	
240	  /* ---------- 顶部数据源 ---------- */
241	  $('#sources').innerHTML = [
242	    ['赛狐 ERP','包裹主干 · '+k.total_orders+' 单'],
243	    ['Temu 库存','货号×库存 · '+D.inventory.codes_indexed],
244	    ['海外仓 WMS','商品主数据 · '+D.inventory.wms_master_count],
245	  ].map(([a,b])=>`<div class="src"><span class="dot"></span><b>${a}</b><span class="c">${esc(b)}</span></div>`).join('');
246	  $('#srcName').textContent = D.meta.source;
247	  $('#snapTime').textContent = D.meta.reference_now||'—';
248	
249	  /* ---------- AI 摘要 ---------- */
250	  const critCombo = O.filter(o=>o.anomalies.includes('stuck_virtual')&&o.anomalies.includes('no_channel'));
251	  const aiOk = k.actionable===0;
252	  const dueSoon = ac.due_soon||0;
253	  const aiHtml = `哨兵扫描 <b class="ok">${k.total_orders}</b> 个订单（${k.platforms} 平台 / ${k.shops} 店铺，赛狐已聚合），`+
254	    `其中 <span class="ok">${k.shipped}</span> 单已发货、当日发货率 <span class="ok">${ls.within24_pct}%</span>，运营总体健康。`+
255	    ` 需你关注：<span class="g">${k.pending}</span> 单待处理中有 <b>${k.actionable}</b> 单需立即动手`+
256	    (dueSoon?`（<span class="g">${dueSoon}</span> 单 24h 内到期）`:'')+
257	    (critCombo.length?`，其中 <b>${critCombo.length}</b> 单同时命中「卡虚拟仓＋缺渠道」将无法出库`:'')+
258	    `；库存侧发现 <b>${D.inventory.temu_zero_stock.length}</b> 个 Temu 断货货号需补货。`;
259	  $('#ai').className='ai panel'+(aiOk?' ok':'');
260	  $('#ai').innerHTML = `<div class="ic">${aiOk?'✅':'🧭'}</div><div class="txt">${aiHtml}</div>`;
261	
262	  /* ---------- KPI ---------- */
